
$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot

Write-Host "============================================================"
Write-Host "GeoPilot Data Requirement Router Foundation V1.1"
Write-Host "PowerShell transport fix for Windows command-length limit"
Write-Host "============================================================"
Write-Host ""

docker compose config --services *> $null
if ($LASTEXITCODE -ne 0) {
    throw "Run from geopilot_v7 root and ensure Docker is running."
}

Write-Host "[1/6] Applying controlled router patch..."
$payload = ""
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace backend python -c "import base64;exec(base64.b64decode('$payload'))"
if ($LASTEXITCODE -ne 0) { throw "Patch step failed" }

Write-Host ""
Write-Host "[2/6] Python compile gate..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend backend python -m compileall app/services/data_requirement_router.py app/services/planning_orchestrator.py tests/test_data_requirement_router.py
if ($LASTEXITCODE -ne 0) { throw "Compile gate failed" }

Write-Host ""
Write-Host "[3/6] Router regression tests..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_data_requirement_router.py
if ($LASTEXITCODE -ne 0) { throw "Router tests failed" }

Write-Host ""
Write-Host "[4/6] Existing Track B regression baseline..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_track_b_hackathon.py
if ($LASTEXITCODE -ne 0) { throw "Track B regression failed" }

Write-Host ""
Write-Host "[5/6] Recreating backend only..."
docker compose up -d --force-recreate backend
if ($LASTEXITCODE -ne 0) { throw "Backend recreate failed" }

Write-Host ""
Write-Host "[6/6] Runtime router verification..."
Start-Sleep -Seconds 4
docker compose exec -T backend python -c "from app.services.data_requirement_router import route_question; r=route_question('berapa slope tertinggi di kawasan ini'); print('STATE=',r.state); print('CAPABILITY=',r.capability); print('TOOLS=',list(r.tools)); print('REQUIRED_EVIDENCE=',list(r.required_evidence)); assert r.state=='evidence_required'; assert 'project_site_dem_or_elevation_raster' in r.required_evidence"
if ($LASTEXITCODE -ne 0) { throw "Runtime verification failed" }

Write-Host ""
Write-Host "============================================================"
Write-Host "DATA REQUIREMENT ROUTER V1.1 GATE PASS"
Write-Host "Terrain questions now fail closed with explicit DEM requirement."
Write-Host "Existing Track B regression suite remains green."
Write-Host "============================================================"
